function executions(ciRunsPerDay, days) {
  return ciRunsPerDay * days;
}

function driftCount(total, loosePercent) {
  return Math.round((total * loosePercent) / 100);
}

const LOOSE = /^[\^~*]|^$/;
function findLooseNames(node) {
  const own = node.range !== null && LOOSE.test(node.range) ? [node.name] : [];
  const below = node.dependencies.flatMap(findLooseNames);
  return own.concat(below);
}

const LOOSE = /^[\^~*]|^$/;
function maxLooseDepth(node, depth = 0) {
  let best = node.range !== null && LOOSE.test(node.range) ? depth : -1;
  for (const child of node.dependencies) {
    best = Math.max(best, maxLooseDepth(child, depth + 1));
  }
  return best;
}

const LOOSE = /^[\^~*]|^$/;
function countLooseTransitive(node, depth = 0) {
  let total = depth >= 2 && LOOSE.test(node.range) ? 1 : 0;
  for (const child of node.dependencies) {
    total += countLooseTransitive(child, depth + 1);
  }
  return total;
}
